package com.bank.ipam;

import java.util.logging.*;

public class IpamDemo {
    private static final Logger log = Logger.getLogger("IPAM");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        IpamAllocator ipam = new IpamAllocator();   // central org-wide pool 10.0.0.0/8
        log.info(() -> "Prod:    " + ipam.allocate("production", "10.0.0.0/16"));
        log.info(() -> "Staging: " + ipam.allocate("staging",    "10.1.0.0/16"));
        log.info(() -> "EKS:     " + ipam.allocate("eks-prod",   "10.10.0.0/16"));
        log.warning(() -> "Clashing request: " + ipam.allocate("rogue", "10.0.0.0/16"));

        SubnetPlanner planner = new SubnetPlanner();
        log.info(() -> "EC2 private subnet size:  /" + planner.prefixFor("ec2"));
        log.info(() -> "EKS pod subnet size:      /" + planner.prefixFor("eks"));
    }
}

