class CidrBlock {
    final String cidr; final int firstOctetBlock;
    CidrBlock(String cidr) {
        this.cidr = cidr;
        this.firstOctetBlock = Integer.parseInt(cidr.split("\\.")[1]); // demo overlap key
    }
    boolean overlaps(CidrBlock other) { return this.firstOctetBlock == other.firstOctetBlock; }
}

// ─── Would be in IpamAllocator.java ───
class IpamAllocator {
    private final java.util.List<CidrBlock> allocated = new java.util.ArrayList<>();
    String allocate(String name, String cidr) {
        CidrBlock block = new CidrBlock(cidr);
        for (CidrBlock b : allocated)
            if (b.overlaps(block))
                return "REJECTED " + cidr + " for " + name + " — overlaps existing allocation";
        allocated.add(block);
        return "ALLOCATED " + cidr + " to " + name;
    }
}

// ─── Would be in SubnetPlanner.java ───
class SubnetPlanner {
    // EKS pods each consume a VPC IP → much larger subnets than plain EC2.
    int prefixFor(String workload) {
        return switch (workload) {
            case "eks" -> 20;   // /20 ~ 4091 usable — room for thousands of pods
            case "ec2" -> 24;   // /24 ~ 251 usable — fine for instances
            default    -> 26;   // small tiers like DB
        };
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
